// Traduce el mensaje de Vapi al contrato /api/voz del backend.
// El cliente y la llamada salen de los metadatos que puso el banco al programar la llamada,
// nunca de lo que se dice en la llamada.
const entrada = $input.first().json;
const api = entrada.api;
const m = entrada.body?.message ?? {};
const call = m.call ?? {};
const vars = call.assistantOverrides?.variableValues ?? {};
const meta = call.metadata ?? {};
const llamadaId = meta.llamadaId ?? vars.llamadaId ?? null;
const clienteId = meta.clienteId ?? vars.clienteId ?? null;

const dias = (v) => (Array.isArray(v) ? v.map(Number).filter((n) => Number.isInteger(n)) : []);
const argumentos = (tc) => {
  let a = tc.arguments ?? tc.parameters ?? tc.function?.arguments ?? {};
  if (typeof a === 'string') {
    try { a = JSON.parse(a); } catch { a = {}; }
  }
  return a;
};
const ingreso = (a) => ({ tipoIngreso: a.tipo_ingreso ?? null, diasIngreso: dias(a.dias_ingreso), semanal: a.semanal ?? null, constante: a.constante ?? null });

if (m.type === 'tool-calls') {
  const pedidas = m.toolCallList ?? (m.toolWithToolCallList ?? []).map((t) => ({ name: t.name, ...t.toolCall }));
  return pedidas.map((tc) => {
    const nombre = tc.name ?? tc.function?.name;
    const a = argumentos(tc);
    const base = { nombre, toolCallId: tc.id };
    if (nombre === 'proponer_fecha') {
      return { json: { ...base, tipo: 'calculo', url: `${api}/voz/fecha/propuesta`, cuerpo: { llamadaId, clienteId, ...ingreso(a) } } };
    }
    if (nombre === 'confirmar_fecha') {
      return { json: { ...base, tipo: 'calculo', url: `${api}/voz/fecha/confirmar`,
        cuerpo: { llamadaId, clienteId, ...ingreso(a), dia: a.dia ?? null, aceptaInteres: a.acepta_interes === true } } };
    }
    if (nombre === 'guardar_formulario') {
      return { json: { ...base, tipo: 'guardar', url: `${api}/voz/llamadas/resultado`,
        cuerpo: { llamadaId, clienteId, resultado: a.resultado ?? null, tipoIngreso: a.tipo_ingreso ?? null, constante: a.constante ?? null,
          diasIngreso: dias(a.dias_ingreso), canalPago: a.canal_pago ?? null, usaBancaLinea: a.usa_banca_linea ?? null } } };
    }
    return { json: { ...base, tipo: 'ignorar' } };
  });
}

if (m.type === 'end-of-call-report') {
  const analisis = m.analysis ?? call.analysis ?? {};
  const datos = analisis.structuredData ?? {};
  const duracion = Number.isFinite(m.durationSeconds) ? m.durationSeconds
    : (Date.parse(call.endedAt) - Date.parse(call.startedAt)) / 1000;
  return [{ json: { tipo: 'guardar', url: `${api}/voz/llamadas/resultado`, cuerpo: {
    llamadaId, clienteId, proveedorId: call.id ?? null, motivoFin: m.endedReason ?? call.endedReason ?? null,
    resultado: datos.resultado ?? null, tipoIngreso: datos.tipo_ingreso ?? null, constante: datos.constante ?? null,
    diasIngreso: dias(datos.dias_ingreso), canalPago: datos.canal_pago ?? null, usaBancaLinea: datos.usa_banca_linea ?? null,
    resumen: analisis.summary ?? null,
    transcripcion: m.artifact?.transcript ?? m.transcript ?? null,
    duracionSeg: Number.isFinite(duracion) ? Math.round(duracion) : null,
  } } }];
}

return [{ json: { tipo: 'ignorar', mensaje: m.type ?? null } }];

// Vapi espera { results: [{ toolCallId, result }] }. El result va corto: menos tokens, menos latencia.
const results = $input.all().map((item, i) => {
  const pedido = $('Leer mensaje de Vapi').itemMatching(i).json;
  const r = item.json;
  const b = r.body ?? {};
  const ok = r.statusCode >= 200 && r.statusCode < 300;
  let result;
  if (!ok) {
    result = { error: b.message ?? 'No se pudo revisar en este momento.' };
  } else if (pedido.nombre === 'confirmar_fecha') {
    result = { decir: b.decir, dia: b.dia, desde: b.desde };
  } else {
    result = { decir: b.decir, bloqueado: b.bloqueado, opciones: (b.opciones ?? []).map((o) => ({ dia: o.dia, desde: o.desde })) };
  }
  return { toolCallId: pedido.toolCallId, result: JSON.stringify(result) };
});
return [{ json: { results } }];
